import json, datetime
from collections import defaultdict

TODAY = datetime.date(2026,7,27)
win_start = TODAY - datetime.timedelta(days=28)  # 4 weeks

# ---- SOCIAL ----
h = json.load(open('analytics/history.json'))
def d(s):
    try: return datetime.date.fromisoformat(s[:10])
    except: return None

posted = [p for p in h if p.get('posted') and d(p['posted']) and d(p['posted'])>=win_start]
print("SOCIAL window", win_start, "to", TODAY, "->", len(posted), "posts")
latest = max((d(p['posted']) for p in h if p.get('posted') and d(p['posted'])), default=None)
print("latest posted date in data:", latest)

def li(p): return (p.get('engagement') or {}).get('linkedin') or {}
def ma(p): return (p.get('engagement') or {}).get('mastodon') or {}
def bs(p): return (p.get('engagement') or {}).get('bluesky') or {}

# LinkedIn top by reactions+comments
liposts=[]
for p in posted:
    e=li(p)
    if e:
        liposts.append((p['posted'], e.get('impressions',0), e.get('reactions',0), e.get('comments',0), (p.get('linkedin') or '')[:60]))
liposts.sort(key=lambda x:(x[2]+x[3]), reverse=True)
print("\n--- LinkedIn top by engagement ---")
for r in liposts[:10]:
    print(f"{r[0]} imp={r[1]} react={r[2]} comm={r[3]} | {r[4]}")

print("\n--- LinkedIn top by reach ---")
for r in sorted(liposts,key=lambda x:x[1],reverse=True)[:4]:
    print(f"{r[0]} imp={r[1]} react={r[2]} comm={r[3]} | {r[4]}")

# Mastodon
maposts=[]
for p in posted:
    e=ma(p)
    if e:
        txt=p.get('mastodon')
        if isinstance(txt,list): txt=' '.join(str(t) for t in txt)
        maposts.append((p['posted'], e.get('favorites',0), e.get('reblogs',0), e.get('replies',0), (txt or '')[:55]))
maposts.sort(key=lambda x:(x[1]+x[2]),reverse=True)
print("\n--- Mastodon top ---")
for r in maposts[:6]:
    print(f"{r[0]} fav={r[1]} reblog={r[2]} rep={r[3]} | {r[4]}")

# Bluesky
print("\n--- Bluesky with engagement ---")
for p in posted:
    e=bs(p)
    if e and (e.get('likes',0)+e.get('comments',0)+e.get('reposts',0))>0:
        print(f"{p['posted']} likes={e.get('likes',0)} comm={e.get('comments',0)} reposts={e.get('reposts',0)} | {(p.get('bluesky') or '')[:50]}")
